              setState(() {
                destinationName = selectedData['description']?.toString();
                destinationAddress = selectedData['address']?.toString();
                destLatitude =
                    selectedData['latitude'] is double
                        ? selectedData['latitude'] as double
                        : double.tryParse(
                              selectedData['latitude'].toString(),
                            ) ??
