      ),
      child: Row(
        children: [
          Container(
            width: 42,
            height: 42,
            decoration: BoxDecoration(
              color: const Color(0xFFF4F7FB),
              borderRadius: BorderRadius.circular(14),
            ),
            child: const Icon(Icons.local_taxi, color: Colors.black87),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  name?.isNotEmpty == true
                      ? '$name is on the way'
                      : 'Driver is on the way',
                  style: const TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 3),
                Text(
                  '${distance ?? 'Live tracking'} • ETA ${eta ?? '--'}',
                  style: TextStyle(
                    fontSize: 11,
                    color: Colors.grey.shade700,
                  ),
                ),
              ],
            ),
          ),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
            decoration: BoxDecoration(
              color: const Color(0xFF0F9D58).withOpacity(0.12),
              borderRadius: BorderRadius.circular(999),
            ),
            child: const Text(
              'Live',
              style: TextStyle(
                color: Color(0xFF0F9D58),
                fontSize: 11,
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Future<void> _handleRideCompleted() async {
    if (!mounted) return;
    _resetRide();
    if (widget.currentLocation == null) return;

    Navigator.pushAndRemoveUntil(
      context,
      MaterialPageRoute(
        builder: (_) => MainBottomNav(selectedLocation: widget.currentLocation!),
      ),
      (route) => false,
    );
  }

  void _handleRideCancelled() {
    if (!mounted) return;
    _resetRide();
    if (widget.currentLocation == null) return;
    Navigator.pushAndRemoveUntil(
      context,
      MaterialPageRoute(
        builder: (_) => MainBottomNav(selectedLocation: widget.currentLocation!),
      ),
      (route) => false,
    );
  }

  void _payCashStatic() {
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(const SnackBar(content: Text("Cash payment successful")));

    _resetRide();
  }

  void _payOnlineStatic() {
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(const SnackBar(content: Text("Online payment successful")));

    _resetRide();
  }

  void _resetRide() {
    setState(() {
      currentState = RideState.searchDestination;
      _markers.clear();
      _polylines.clear();
      _driverPolylines.clear();
      _driverMarker = null;
      _driverMarkerAdded = false;
      _driverLocation = null;
      _driverInfo = null;
      _driverOtp = null;
    });
  }

  Widget _buildEditPickupScreen(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        leading: IconButton(
          icon: Icon(Icons.arrow_back, color: Colors.black),
          onPressed: () => goTo(RideState.pickupDrop),
        ),
        title: Text(
          "Edit Pickup Location",
          style: TextStyle(color: Colors.black),
        ),
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            Expanded(
              flex: 2,
              child: CommonGoogleMap(
                initialLatLng:
                    widget.currentLocation != null
                        ? LatLng(
                          widget.currentLocation!.latitude,
                          widget.currentLocation!.longitude,
                        )
                        : const LatLng(19.0760, 72.8777),
                height: 200,
                markers: {
                  Marker(
                    markerId: const MarkerId('edit_pickup'),
                    position:
                        widget.currentLocation != null
                            ? LatLng(
                              widget.currentLocation!.latitude,
                              widget.currentLocation!.longitude,
                            )
                            : const LatLng(19.0760, 72.8777),
                    icon: BitmapDescriptor.defaultMarkerWithHue(
                      BitmapDescriptor.hueGreen,
                    ),
                  ),
                },
              ),
            ),

            SizedBox(height: 16),
            Expanded(
              flex: 3,
              child: SearchDestinationUI(
                currentLocation: _pickupLocation,
                onSearchTap: () {
                  print('Opening map for pickup location');
                },
                onNext: (selectedData) {
                  if (selectedData != null && selectedData.isNotEmpty) {
                    print('Pickup updated via Next button');
                    print('New Location: ${selectedData['description']}');
                  }
                  goTo(RideState.pickupDrop);
                },
                mode: 'pickup',
                initialValue: _pickupLocation?.address,
                onDestinationSelected: (locationData) {
                  print(
                    'Pickup location selected from search: ${locationData['description']}',
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildEditDropoffScreen(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        leading: IconButton(
          icon: Icon(Icons.arrow_back, color: Colors.black),
          onPressed: () => goTo(RideState.pickupDrop),
        ),
        title: Text(
          "Edit Dropoff Location",
          style: TextStyle(color: Colors.black),
        ),
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            Expanded(
              flex: 2,
              child: CommonGoogleMap(
                initialLatLng:
                    destLatitude != null && destLongitude != null
                        ? LatLng(destLatitude!, destLongitude!)
                        : LatLng(19.0760, 72.8777),
                height: 200,
                markers: {
  Marker(
                    markerId: const MarkerId('edit_dropoff'),
                    position:
                        destLatitude != null && destLongitude != null
                            ? LatLng(destLatitude!, destLongitude!)
                            : const LatLng(19.0760, 72.8777),
                    icon: BitmapDescriptor.defaultMarkerWithHue(
                      BitmapDescriptor.hueRed,
                    ),
                  ),
                },
              ),
            ),
            SizedBox(height: 16),
            Expanded(
              flex: 3,
              child: SearchDestinationUI(
                currentLocation: widget.currentLocation,
                onSearchTap: () {
                  print('Opening map for dropoff location');
                },
                onNext: (selectedData) {
                  if (selectedData != null && selectedData.isNotEmpty) {
                    setState(() {
                      destinationName = selectedData['description']?.toString();
                      destinationAddress = selectedData['address']?.toString();
                      destLatitude = selectedData['latitude'];
                      destLongitude = selectedData['longitude'];
                    });
                    print('Dropoff updated via Next button');
                  }
                  goTo(RideState.pickupDrop);
                },
                mode: 'dropoff',
                initialValue: destinationAddress,
                onDestinationSelected: (locationData) {
                  print(
                    'Dropoff location selected from search: ${locationData['description']}',
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}
